contract InvMutTest {
    C c;

    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    // - hash: bytes32 to lock
    // - lockAmount: amount of wei to send to lockInGuess (should be exactly 1 ether to succeed)
    // - trySecondLockAmount: amount to attempt second lock (we will use 1 ether to check clearing)
    function run(bytes32 hash, uint lockAmount, uint trySecondLockAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (lockAmount) + (trySecondLockAmount)); require(lockAmount <= 1000000000000000000000000000000); require(trySecondLockAmount <= 1000000000000000000000000000000);
        // ensure test contract has enough balance to send lockAmount and potential second lock
        require(address(this).balance >= lockAmount);
        require(address(this).balance >= trySecondLockAmount);

        // Attempt first lockInGuess and record whether it reverted
        bool firstLockReverted;
        c.lockInGuess{value: lockAmount}(hash); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstLockReverted = true;
        } else {
            firstLockReverted = false;
        }

        // Observe contract balance after first attempt
        uint balAfterFirst = address(c).balance;

        // Attempt settle and record whether it reverted
        bool settleReverted;
        c.settle(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            settleReverted = true;
        } else {
            settleReverted = false;
        }

        // Observe contract balance after settle
        uint balAfterSettle = address(c).balance;

        // Attempt a second lock with provided amount to test whether guess was cleared
        bool secondLockReverted;
        c.lockInGuess{value: trySecondLockAmount}(hash); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            secondLockReverted = true;
        } else {
            secondLockReverted = false;
        }

        // Assert the invariant:
        // If the first lock succeeded then either:
        //  - settle reverted, and contract balance did not decrease (balAfterSettle >= balAfterFirst), or
        //  - settle succeeded, and the pending guess was cleared allowing a subsequent lock to succeed (secondLockReverted == false), and contract balance decreased by at most 2 ether (balAfterFirst >= balAfterSettle and balAfterFirst - balAfterSettle <= 2 ether).
        // If the first lock failed we do not require anything else.
        assert(
            firstLockReverted
            || (
                settleReverted && (balAfterSettle >= balAfterFirst)
            )
            || (
                (!settleReverted) && (!secondLockReverted) && (balAfterFirst >= balAfterSettle) && (balAfterFirst - balAfterSettle <= 2 ether)
            )
        );
    }

    // Allow receiving Ether when settle pays out
    receive() external payable {}
}

