// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 hash, uint256 lockAmount, uint256 trySecondLockAmount) internal {
        lockAmount = bound(lockAmount, 0, 1000000000000000000000000000000);
        trySecondLockAmount = bound(trySecondLockAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= lockAmount);
        vm.assume(address(this).balance >= trySecondLockAmount);
        bool firstLockReverted;
        try c.lockInGuess{value: lockAmount}(hash) {
            firstLockReverted = false;
        } catch {
            firstLockReverted = true;
        }
        uint balAfterFirst = address(c).balance;
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint balAfterSettle = address(c).balance;
        bool secondLockReverted;
        try c.lockInGuess{value: trySecondLockAmount}(hash) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }
        assertTrue(firstLockReverted
            || (
                settleReverted && (balAfterSettle >= balAfterFirst)
            )
            || (
                (!settleReverted) && (!secondLockReverted) && (balAfterFirst >= balAfterSettle) && (balAfterFirst - balAfterSettle <= 2 ether)
            ));
    }

    function testFuzz_run(bytes32 hash, uint256 lockAmount, uint256 trySecondLockAmount) public {
        _run(hash, lockAmount, trySecondLockAmount);
    }

    receive() external payable {}
}
